select 'ledger' k, coalesce((select version||' | '||name||' | created_by='||coalesce(created_by,'<null>')||' | stmts='||coalesce(array_length(statements,1),0)::text from supabase_migrations.schema_migrations where version='20260924120000'),'<no row>') v
union all select 'ledger_rows', count(*)::text from supabase_migrations.schema_migrations
union all select 'fn', n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||') md5='||md5(pg_get_functiondef(p.oid))||' secdef='||p.prosecdef::text||' cfg='||coalesce(array_to_string(p.proconfig,';'),'<none>') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname,p.proname) in (('public','record_payout_attempt_result'),('public','flag_payout_reversal_required'))
union all select 'fn_prosrc', n.nspname||'.'||p.proname||' prosrc_md5='||md5(p.prosrc) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname,p.proname) in (('public','record_payout_attempt_result'),('public','flag_payout_reversal_required'))
union all select 'fn_grants', n.nspname||'.'||p.proname||' anon='||has_function_privilege('anon',p.oid,'execute')::text||' authenticated='||has_function_privilege('authenticated',p.oid,'execute')::text||' service_role='||has_function_privilege('service_role',p.oid,'execute')::text from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname,p.proname) in (('public','record_payout_attempt_result'),('public','flag_payout_reversal_required'))
union all select 'census', 'tables='||(select count(*) from pg_tables where schemaname='public')||' functions='||(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public')||' policies='||(select count(*) from pg_policies where schemaname='public')||' triggers='||(select count(*) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal)
union all select 'switch', key||'='||value::text from ops.setting where key in ('refund_resolution_detector_enabled','alert_delivery_enabled','detectors_enabled')
union all select 'ops_alert_cols', (select count(*)::text from information_schema.columns where table_schema='ops' and table_name='alert')
union all select 'grants', (select string_agg(grantee||'|'||table_name||'|'||privs, E'\n' order by grantee, table_name) from (select grantee, table_name, string_agg(privilege_type, ',' order by privilege_type) privs from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated','service_role') group by grantee, table_name) g)
union all select 'now', now()::text
